// Agoda — backspace string compare (LeetCode 844), then without allocating.
public static class Backspace {
    // '#' deletes the previous character (if any). Are the two typed results equal?
    // Two pointers from the end: O(n) time, O(1) extra space, no allocation.
    public static bool Compare(string s, string t) {
        s ??= ""; t ??= "";
        int i = s.Length - 1, j = t.Length - 1;
        while (true) {
            i = NextKept(s, i); j = NextKept(t, j);
            if (i < 0 || j < 0) return i < 0 && j < 0;
            if (s[i] != t[j]) return false;
            i--; j--;
        }
    }

    // Index of the next character, scanning left from i, that survives the backspaces; -1 if none.
    static int NextKept(string s, int i) {
        int skip = 0;
        while (i >= 0) {
            if (s[i] == '#') { skip++; i--; }
            else if (skip > 0) { skip--; i--; }
            else return i;
        }
        return -1;
    }

    // The final text after applying the backspaces.
    public static string Typed(string s) {
        if (string.IsNullOrEmpty(s)) return "";
        var sb = new System.Text.StringBuilder(s.Length);
        foreach (var c in s) { if (c == '#') { if (sb.Length > 0) sb.Length--; } else sb.Append(c); }
        return sb.ToString();
    }
}
