public static class Playground {
    public static void Main() {
        try {
            Expect.Do("ab#c == ad#c", () => { Expect.True("ab#c == ad#c", Backspace.Compare("ab#c", "ad#c")); });
            Expect.Do("ab## == c#d#", () => { Expect.True("ab## == c#d#", Backspace.Compare("ab##", "c#d#")); });
            Expect.Do("a#c != b", () => { Expect.True("a#c != b", !Backspace.Compare("a#c", "b")); });
        } catch (Exception e) { Expect.Setup(e); }
        Expect.Summary(7);
    }
}

// The example checker. ✓ = your result matches, ✗ = it does not (or the method is not written yet).
static class Expect {
    static int pass, fail;
    static string Show(object o) => o is string s ? "\"" + s + "\"" : (o?.ToString() ?? "null");
    static void Report(bool ok, string what, string got, string want) {
        if (ok) { pass++; Console.WriteLine("✓ " + what); }
        else { fail++; Console.WriteLine("✗ " + what + "\n    got  " + got + "\n    want " + want); }
    }
    public static void Eq<TV>(string what, TV got, TV want) => Report(EqualityComparer<TV>.Default.Equals(got, want), what, Show(got), Show(want));
    public static void True(string what, bool ok) => Report(ok, what, ok.ToString(), "True");
    public static void Seq<TV>(string what, IEnumerable<TV> got, params TV[] want) {
        var g = got == null ? new List<TV>() : new List<TV>(got);
        bool ok = g.Count == want.Length;
        for (int i = 0; ok && i < g.Count; i++) ok = EqualityComparer<TV>.Default.Equals(g[i], want[i]);
        Report(ok, what, "[" + string.Join(", ", g) + "]", "[" + string.Join(", ", want) + "]");
    }
    public static void Throws<TE>(string what, Action a) where TE : Exception {
        try { a(); Report(false, what, "no exception", typeof(TE).Name); }
        catch (TE) { Report(true, what, "", ""); }
    }
    // Runs one example; a crash or a missing method is a ✗, and the next example still runs.
    public static void Do(string what, Action a) {
        try { a(); }
        catch (NotImplementedException e) { fail++; Console.WriteLine("✗ " + what + "\n    not written yet: " + Where(e)); }
        catch (Exception e) { fail++; Console.WriteLine("✗ " + what + "\n    crashed: " + e.GetType().Name + ": " + e.Message + " " + Where(e)); }
    }
    public static void Setup(Exception e) {
        fail++;
        Console.WriteLine(e is NotImplementedException ? "✗ setup stopped — not written yet: " + Where(e)
                                                       : "✗ setup crashed: " + e.GetType().Name + ": " + e.Message + " " + Where(e));
    }
    static string Where(Exception e) {
        foreach (var line in (e.StackTrace ?? "").Split('\n'))
            if (line.Contains(" at ") && !line.Contains("Expect.") && !line.Contains("Playground.")) {
                string t = line.Trim().Substring(3);                       // "Isomorphic.Check(String s) in /long/path/Isomorphic.cs:line 2"
                int k = t.IndexOf(" in ");
                if (k < 0) return "(" + t + ")";
                string file = t.Substring(k + 4); int slash = file.LastIndexOfAny(new[] { '/', '\\' });
                return "(" + file.Substring(slash + 1) + ")";              // -> "(Isomorphic.cs:line 2)"
            }
        return "";
    }
    public static void Summary(int total) {
        Console.WriteLine();
        Console.WriteLine("Examples: " + pass + " passed, " + fail + " failed.  ✓ Run all tests checks all " + total + " test cases for the parts revealed so far.");
    }
}

